import fitz
doc = fitz.open('{{SESSION_PATH}}/data/冰箱全品牌全方位对比分析报告.pdf')
issues = []
for i, page in enumerate(doc):
    t = page.get_text()
    # check for bad chars
    for ch in ['?C', 'mathrm', '?Frac']:
        if ch in t:
            issues.append(f'Page {i+1}: found {ch}')
    # Check for degree symbol correctness
    if ' -30度' not in t and '-30' in t and i < 5:
        issues.append(f'Page {i+1}: possible bad degree symbol')
print(f'Total pages: {len(doc)}')
print(f'Issues found: {len(issues)}')
for issue in issues:
    print(f'  - {issue}')
if not issues:
    print('All clear - no encoding issues detected')
"

